const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const lon = -125.410394;
    const lat = -41.729403;
    const region = ee.Geometry.Point([lon, lat]).buffer(100000); // 100 km radius
    const scale = 4000;

    const p1Start = '2018-11-01';
    const p1End = '2019-03-01'; // exclusive
    const p2Start = '2019-11-01';
    const p2End = '2020-03-01'; // exclusive

    // Helper to get stats for a period
    function getPeriodStats(startStr, endStr, label) {
      // Base collection
      let col = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
        .select('chlor_a')
        .filterDate(startStr, endStr)
        .filterBounds(region);

      let size = col.size().getInfo();
      console.log(`${label} Images: ${size}`);

      // Recovery if empty: widen date window by ±15 days
      if (size === 0) {
        const startW = ee.Date(startStr).advance(-15, 'day');
        const endW = ee.Date(endStr).advance(15, 'day');
        col = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
          .select('chlor_a')
          .filterDate(startW, endW)
          .filterBounds(region);
        size = col.size().getInfo();
        console.log(`${label} Recovery (±15d) Images: ${size}`);
        if (size === 0) {
          return { exitTag: 'C1' };
        }
      }

      // Mask non-positive values
      col = col.map(function(img) {
        const band = img.select('chlor_a');
        return img.updateMask(band.gt(0));
      });

      // Time-mean over the period
      const meanImg = col.mean().rename('chlor_a');

      // Valid pixel count within region
      const validCount = ee.Number(
        meanImg.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9
        }).get('chlor_a')
      ).getInfo();

      // Total pixel count (at given scale)
      const totalCount = ee.Number(
        ee.Image.constant(1).rename('one').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9
        }).get('one')
      ).getInfo();

      const validPct = totalCount > 0 ? (validCount / totalCount) * 100.0 : 0;

      if (!validCount || validCount === 0) {
        return {
          exitTag: 'C2',
          size,
          validCount,
          totalCount,
          validPct
        };
      }

      // Spatial mean of time-mean chlorophyll
      const meanVal = ee.Number(
        meanImg.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9
        }).get('chlor_a')
      ).getInfo();

      if (meanVal === null || isNaN(meanVal) || meanVal <= 0 || meanVal > 1000) {
        return { exitTag: 'C3' };
      }

      console.log(`${label} Valid Pixels: ${validCount}/${totalCount} (${validPct.toFixed(1)}%)`);
      console.log(`${label} Mean chlor_a (mg/m^3): ${meanVal.toFixed(3)}`);

      return {
        exitTag: null,
        size,
        validCount,
        totalCount,
        validPct,
        meanVal
      };
    }

    console.log('Dataset: NASA/OCEANDATA/MODIS-Aqua/L3SMI chlor_a');

    // 2. Data Acquisition & Checks
    const s1 = getPeriodStats(p1Start, p1End, '2018-2019 (Nov–Feb)');
    if (s1.exitTag) {
      console.log(`Early exit: ${s1.exitTag}`);
      console.log(s1.exitTag);
      return;
    }

    const s2 = getPeriodStats(p2Start, p2End, '2019-2020 (Nov–Feb)');
    if (s2.exitTag) {
      console.log(`Early exit: ${s2.exitTag}`);
      console.log(s2.exitTag);
      return;
    }

    // 3. Calculation: change assessment
    const diff = s2.meanVal - s1.meanVal;
    const pct = s1.meanVal > 0 ? (diff / s1.meanVal) * 100.0 : null;

    if (!isFinite(diff) || (pct !== null && !isFinite(pct))) {
      console.log('Invalid change calculation.');
      console.log('C3');
      return;
    }

    console.log(`Change: ${diff.toFixed(3)} mg/m^3 (${pct !== null ? pct.toFixed(1) : 'NA'}%)`);

    // 4. Final Answer
    const answer = diff > 0 ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
